CREATE TABLE IF NOT EXISTS v2_stage_user_account (
 user_id VARCHAR(64) PRIMARY KEY, employee_no VARCHAR(64) NOT NULL,
 display_name VARCHAR(255) NOT NULL, department_id VARCHAR(64) NOT NULL,
 identity_source VARCHAR(64) NOT NULL, enabled TINYINT(1) NOT NULL,
 last_identity_sync_at DATETIME(6), version BIGINT NOT NULL DEFAULT 0,
 created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
 UNIQUE KEY uk_user_employee_no(employee_no), KEY idx_user_department(department_id),
 KEY idx_user_enabled(enabled),
  password_hash VARCHAR(100) COMMENT 'Compatibility: local BCrypt authentication; remove after SSO rollout'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_user_role (
 user_id VARCHAR(64) NOT NULL, role_code VARCHAR(32) NOT NULL,
 granted_by VARCHAR(64) NOT NULL, granted_at DATETIME(6) NOT NULL,
 revoked_at DATETIME(6), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
 PRIMARY KEY(user_id,role_code), KEY idx_role_revoked(revoked_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_support_team (
 team_id VARCHAR(64) PRIMARY KEY, name VARCHAR(255) NOT NULL, enabled TINYINT(1) NOT NULL,
 version BIGINT NOT NULL DEFAULT 0, created_at DATETIME(6) NOT NULL,
 updated_at DATETIME(6) NOT NULL, UNIQUE KEY uk_team_name(name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_team_member (
 team_id VARCHAR(64) NOT NULL, engineer_id VARCHAR(64) NOT NULL,
 joined_at DATETIME(6) NOT NULL, left_at DATETIME(6), enabled TINYINT(1) NOT NULL,
 created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
 PRIMARY KEY(team_id,engineer_id), KEY idx_member_engineer(engineer_id,enabled)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_engineer_runtime_state (
 engineer_id VARCHAR(64) PRIMARY KEY, presence VARCHAR(32) NOT NULL,
 last_activity_at DATETIME(6), last_assigned_at DATETIME(6),
 version BIGINT NOT NULL DEFAULT 0, created_at DATETIME(6) NOT NULL,
 updated_at DATETIME(6) NOT NULL, KEY idx_engineer_presence(presence,last_activity_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_engineer_category_capability (
 engineer_id VARCHAR(64) NOT NULL, category_id VARCHAR(64) NOT NULL,
 team_id VARCHAR(64) NOT NULL, enabled TINYINT(1) NOT NULL,
 effective_at DATETIME(6) NOT NULL, expired_at DATETIME(6),
 created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
 PRIMARY KEY(engineer_id,category_id,team_id,effective_at),
 KEY idx_capability_route(category_id,team_id,enabled)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_category (
 category_id VARCHAR(64) PRIMARY KEY, parent_id VARCHAR(64),
 nature VARCHAR(32) NOT NULL, name VARCHAR(255) NOT NULL, level SMALLINT NOT NULL,
 definition_version VARCHAR(64) NOT NULL, enabled TINYINT(1) NOT NULL,
 version BIGINT NOT NULL DEFAULT 0, created_at DATETIME(6) NOT NULL,
 updated_at DATETIME(6) NOT NULL, KEY idx_category_parent(parent_id,level,enabled)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_category_route (
 category_id VARCHAR(64) NOT NULL, team_id VARCHAR(64) NOT NULL,
 route_order INT NOT NULL, effective_at DATETIME(6) NOT NULL, expired_at DATETIME(6),
 created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
 PRIMARY KEY(category_id,team_id,effective_at),
 UNIQUE KEY uk_route_order(category_id,route_order,effective_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_consultation (
 session_id VARCHAR(32) PRIMARY KEY, creator_id VARCHAR(64) NOT NULL,
 category_id VARCHAR(64), status VARCHAR(32) NOT NULL, current_engineer_id VARCHAR(64),
 source VARCHAR(32) NOT NULL, resolution_type VARCHAR(32), converted_ticket_id VARCHAR(32),
 closed_at DATETIME(6), version BIGINT NOT NULL DEFAULT 0,
 created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
 KEY idx_consult_creator(creator_id,status,created_at),
 KEY idx_consult_engineer(current_engineer_id,status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_consultation_message (
 message_id VARCHAR(64) PRIMARY KEY, session_id VARCHAR(32) NOT NULL,
 sender_id VARCHAR(64), sender_type VARCHAR(32) NOT NULL, client_message_id VARCHAR(64) NOT NULL,
 content MEDIUMTEXT NOT NULL,
 citation_json JSON, sent_at DATETIME(6) NOT NULL, withdrawn_at DATETIME(6),
 withdraw_reason VARCHAR(2000), created_at DATETIME(6) NOT NULL,
 updated_at DATETIME(6) NOT NULL,
 KEY idx_consult_message(session_id,sent_at,message_id),
 UNIQUE KEY uk_consult_client_message(session_id,client_message_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_ticket_draft (
 draft_id VARCHAR(64) PRIMARY KEY, creator_id VARCHAR(64) NOT NULL,
 nature VARCHAR(32), category_id VARCHAR(64), payload_json JSON NOT NULL,
 last_saved_at DATETIME(6) NOT NULL, expires_at DATETIME(6) NOT NULL,
 version BIGINT NOT NULL DEFAULT 0, created_at DATETIME(6) NOT NULL,
 updated_at DATETIME(6) NOT NULL, UNIQUE KEY uk_active_draft(creator_id),
  title VARCHAR(100),
 description TEXT,
 impact_description TEXT,
 urgency_description TEXT,
 location VARCHAR(255),
 contact VARCHAR(255),
 asset_id VARCHAR(64)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_assignment (
 assignment_id VARCHAR(64) PRIMARY KEY, biz_type VARCHAR(32) NOT NULL,
 biz_id VARCHAR(64) NOT NULL, engineer_id VARCHAR(64) NOT NULL,
 assigned_at DATETIME(6) NOT NULL, response_deadline DATETIME(6),
 responded_at DATETIME(6), end_reason VARCHAR(32),
 created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
 KEY idx_assignment_object(biz_type,biz_id,assigned_at),
 KEY idx_assignment_engineer(engineer_id,end_reason)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_sla_instance (
 sla_id VARCHAR(64) PRIMARY KEY, biz_type VARCHAR(32) NOT NULL,
 biz_id VARCHAR(64) NOT NULL, sla_type VARCHAR(32) NOT NULL, status VARCHAR(32) NOT NULL,
 target_work_seconds BIGINT NOT NULL, elapsed_work_seconds BIGINT NOT NULL DEFAULT 0,
 paused_seconds BIGINT NOT NULL DEFAULT 0, target_at DATETIME(6),
 breached_at DATETIME(6), met_at DATETIME(6), calendar_id VARCHAR(64) NOT NULL,
 calendar_version BIGINT NOT NULL, version BIGINT NOT NULL DEFAULT 0,
 created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
 UNIQUE KEY uk_sla_business(biz_type,biz_id,sla_type),
 KEY idx_sla_due(status,target_at),
  priority_snapshot VARCHAR(32),
 near_breach_notified TINYINT(1) NOT NULL DEFAULT 0
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_sla_pause (
 pause_id VARCHAR(64) PRIMARY KEY, sla_id VARCHAR(64) NOT NULL,
 reason_type VARCHAR(32) NOT NULL, started_at DATETIME(6) NOT NULL,
 ended_at DATETIME(6), operator_id VARCHAR(64) NOT NULL,
 created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
 KEY idx_sla_pause(sla_id,started_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_notification (
 notification_id VARCHAR(64) PRIMARY KEY, event_id VARCHAR(64) NOT NULL,
 receiver_id VARCHAR(64) NOT NULL, channel VARCHAR(32) NOT NULL,
 dedup_key VARCHAR(255) NOT NULL, status VARCHAR(32) NOT NULL,
 attempts INT NOT NULL DEFAULT 0, last_error VARCHAR(1000), sent_at DATETIME(6),
 read_at DATETIME(6), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
 UNIQUE KEY uk_notification_dedup(dedup_key), KEY idx_notification_receiver(receiver_id,status),
  title VARCHAR(100),
 content VARCHAR(500),
 action_url VARCHAR(200)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_audit_log (
 audit_id VARCHAR(64) PRIMARY KEY, actor_id VARCHAR(64), action VARCHAR(128) NOT NULL,
 object_type VARCHAR(64) NOT NULL, object_id VARCHAR(64) NOT NULL,
 before_json JSON, after_json JSON, reason VARCHAR(2000), request_id VARCHAR(128) NOT NULL,
 occurred_at DATETIME(6) NOT NULL, created_at DATETIME(6) NOT NULL,
 updated_at DATETIME(6) NOT NULL,
 KEY idx_audit_object(object_type,object_id,occurred_at),
 KEY idx_audit_actor(actor_id,occurred_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_idempotency_record (
 record_id VARCHAR(64) PRIMARY KEY, owner_id VARCHAR(64) NOT NULL,
 operation VARCHAR(128) NOT NULL, idempotency_key VARCHAR(128) NOT NULL,
 request_hash CHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, result_json JSON,
 expires_at DATETIME(6) NOT NULL, created_at DATETIME(6) NOT NULL,
 updated_at DATETIME(6) NOT NULL,
 UNIQUE KEY uk_idempotency(owner_id,operation,idempotency_key),
 KEY idx_idempotency_expiry(expires_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_outbox_event (
 event_id VARCHAR(64) PRIMARY KEY, event_type VARCHAR(64) NOT NULL,
 aggregate_type VARCHAR(64) NOT NULL, aggregate_id VARCHAR(64) NOT NULL,
 event_version INT NOT NULL, aggregate_version BIGINT NOT NULL,
 payload_json JSON NOT NULL, status VARCHAR(32) NOT NULL,
 attempts INT NOT NULL DEFAULT 0, next_attempt_at DATETIME(6),
 published_at DATETIME(6), created_at DATETIME(6) NOT NULL,
 updated_at DATETIME(6) NOT NULL,
 KEY idx_outbox_publish(status,next_attempt_at),
 UNIQUE KEY uk_aggregate_version(aggregate_type,aggregate_id,aggregate_version)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_knowledge_article (
 article_id VARCHAR(64) PRIMARY KEY, status VARCHAR(32) NOT NULL,
 current_version_id VARCHAR(64), category_id VARCHAR(64) NOT NULL,
 risk_level VARCHAR(32) NOT NULL, version BIGINT NOT NULL DEFAULT 0,
 created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
 KEY idx_knowledge_status(status,category_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_knowledge_version (
 version_id VARCHAR(64) PRIMARY KEY, article_id VARCHAR(64) NOT NULL,
 version_no INT NOT NULL, content_json JSON NOT NULL, author_id VARCHAR(64) NOT NULL,
 reviewer_id VARCHAR(64), published_at DATETIME(6), change_note VARCHAR(2000),
 platform_reviewer_id VARCHAR(64), platform_reviewed_at DATETIME(6),
 platform_review_decision VARCHAR(32),
 created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
 UNIQUE KEY uk_knowledge_version(article_id,version_no),
  search_text TEXT GENERATED ALWAYS AS (CONCAT_WS(' ', JSON_UNQUOTE(JSON_EXTRACT(content_json, '$.title')), JSON_UNQUOTE(JSON_EXTRACT(content_json, '$.summary')), JSON_UNQUOTE(JSON_EXTRACT(content_json, '$.keywords')), JSON_UNQUOTE(JSON_EXTRACT(content_json, '$.body')))) STORED,
 FULLTEXT KEY ft_knowledge_search(search_text) WITH PARSER ngram
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_ai_interaction (
 interaction_id VARCHAR(64) PRIMARY KEY, session_id VARCHAR(32) NOT NULL,
 model_version VARCHAR(128) NOT NULL, retrieved_versions_json JSON NOT NULL,
 confidence DECIMAL(8,4), feedback VARCHAR(32), latency_ms BIGINT NOT NULL,
 occurred_at DATETIME(6) NOT NULL, created_at DATETIME(6) NOT NULL,
 updated_at DATETIME(6) NOT NULL, KEY idx_ai_session(session_id,occurred_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_ticket (
  ticket_id VARCHAR(32) PRIMARY KEY, creator_id VARCHAR(64) NOT NULL,
  ticket_nature VARCHAR(32) NOT NULL, category_id VARCHAR(64) NOT NULL,
  title VARCHAR(100) NOT NULL, description TEXT NOT NULL,
  impact_description TEXT NOT NULL, urgency_description TEXT NOT NULL,
  location VARCHAR(255), contact VARCHAR(255), asset_id VARCHAR(64),
  status VARCHAR(32) NOT NULL, priority VARCHAR(32) NOT NULL,
  assignee_id VARCHAR(64), source_session_id VARCHAR(32),
  field_snapshot_json JSON, version BIGINT NOT NULL DEFAULT 0,
  created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
  completed_at DATETIME(6), closed_at DATETIME(6),
  KEY idx_ticket_creator_status (creator_id,status),
  KEY idx_ticket_assignee_status (assignee_id,status),
  KEY idx_ticket_priority_status (priority,status),
  category_snapshot VARCHAR(500),
 asset_check_status VARCHAR(32),
 impact_scope VARCHAR(32),
 urgency_level VARCHAR(32),
 auto_accepted TINYINT(1) NOT NULL DEFAULT 0,
 reopen_count INT NOT NULL DEFAULT 0,
 idempotency_key VARCHAR(128),
 first_response_at DATETIME(6),
 solved_at DATETIME(6),
 rating_score INT,
 rating_comment VARCHAR(2000),
 rated_at DATETIME(6),
 KEY idx_ticket_title_category(title,category_id,created_at),
 KEY idx_ticket_source_session(source_session_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_ticket_transition (
  transition_id VARCHAR(64) PRIMARY KEY, ticket_id VARCHAR(32) NOT NULL,
  from_status VARCHAR(32), to_status VARCHAR(32) NOT NULL,
  event_code VARCHAR(64) NOT NULL, operator_id VARCHAR(64) NOT NULL,
  reason TEXT, occurred_at DATETIME(6) NOT NULL,
  UNIQUE KEY uk_transition_order (ticket_id,occurred_at,transition_id),
  KEY idx_transition_ticket (ticket_id,occurred_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_service_calendar (
  calendar_id VARCHAR(64) PRIMARY KEY, timezone VARCHAR(64) NOT NULL,
  work_week_json JSON NOT NULL, work_intervals_json JSON NOT NULL,
  lunch_pauses TINYINT(1) NOT NULL DEFAULT 1, version BIGINT NOT NULL DEFAULT 0,
  effective_from DATETIME(6) NOT NULL, effective_to DATETIME(6),
  created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_calendar_holiday (
  holiday_id VARCHAR(64) PRIMARY KEY, calendar_id VARCHAR(64) NOT NULL,
  holiday_date DATE NOT NULL, name VARCHAR(255) NOT NULL,
  is_working_day TINYINT(1) NOT NULL DEFAULT 0,
  UNIQUE KEY uk_calendar_date (calendar_id,holiday_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS v2_stage_exception_queue (
  exception_id VARCHAR(64) PRIMARY KEY, object_type VARCHAR(32) NOT NULL,
  object_id VARCHAR(64) NOT NULL, reason_code VARCHAR(64) NOT NULL,
  status VARCHAR(32) NOT NULL, claimed_by VARCHAR(64), claimed_at DATETIME(6),
  resolved_by VARCHAR(64), resolved_at DATETIME(6), reason TEXT,
  created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
  KEY idx_exception_status (status,created_at),
  UNIQUE KEY uk_exception_open (object_type,object_id,reason_code,status),
  title VARCHAR(100),
 detail VARCHAR(1000),
 priority VARCHAR(32)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

DELIMITER $$
CREATE PROCEDURE migration_v2_copy()
BEGIN
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 START TRANSACTION;
INSERT INTO `v2_stage_user_role` (`user_id`,`role_code`,`granted_by`,`granted_at`,`revoked_at`,`created_at`,`updated_at`)
SELECT s.`user_id`, CASE s.role_code WHEN 'KB_ADMIN' THEN 'KNOWLEDGE_ADMIN' ELSE s.role_code END, COALESCE(s.granted_by,'SYSTEM'), CONVERT_TZ(s.`granted_at`, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.`revoked_at`, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.`created_at`, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.created_at, @main_source_utc_offset, '+00:00')
FROM `user_role` s;
INSERT INTO migration_v2_counts (source_table,target_table,source_rows,staged_rows) SELECT 'user_role','user_role',(SELECT COUNT(*) FROM `user_role`),(SELECT COUNT(*) FROM `v2_stage_user_role`);
INSERT INTO `v2_stage_support_team` (`team_id`,`name`,`enabled`,`version`,`created_at`,`updated_at`)
SELECT s.`team_id`, s.`name`, s.status='ACTIVE', 0, CONVERT_TZ(s.`created_at`, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.`updated_at`, @main_source_utc_offset, '+00:00')
FROM `support_team` s;
INSERT INTO migration_v2_counts (source_table,target_table,source_rows,staged_rows) SELECT 'support_team','support_team',(SELECT COUNT(*) FROM `support_team`),(SELECT COUNT(*) FROM `v2_stage_support_team`);
INSERT INTO `v2_stage_team_member` (`team_id`,`engineer_id`,`joined_at`,`left_at`,`enabled`,`created_at`,`updated_at`)
SELECT s.`team_id`, s.`engineer_id`, CONVERT_TZ(s.`joined_at`, @main_source_utc_offset, '+00:00'), NULL, s.status='ACTIVE', CONVERT_TZ(s.`created_at`, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.created_at, @main_source_utc_offset, '+00:00')
FROM `team_member` s;
INSERT INTO migration_v2_counts (source_table,target_table,source_rows,staged_rows) SELECT 'team_member','team_member',(SELECT COUNT(*) FROM `team_member`),(SELECT COUNT(*) FROM `v2_stage_team_member`);
INSERT INTO `v2_stage_category` (`category_id`,`parent_id`,`nature`,`name`,`level`,`definition_version`,`enabled`,`version`,`created_at`,`updated_at`)
SELECT s.`category_id`, s.`parent_id`, s.ticket_nature, s.`name`, s.`level`, 'legacy-main-v1', s.status='ACTIVE', s.`version`, CONVERT_TZ(s.`created_at`, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.`updated_at`, @main_source_utc_offset, '+00:00')
FROM `category` s;
INSERT INTO migration_v2_counts (source_table,target_table,source_rows,staged_rows) SELECT 'category','category',(SELECT COUNT(*) FROM `category`),(SELECT COUNT(*) FROM `v2_stage_category`);
INSERT INTO `v2_stage_category_route` (`category_id`,`team_id`,`route_order`,`effective_at`,`expired_at`,`created_at`,`updated_at`)
SELECT s.`category_id`, s.`team_id`, s.`route_order`, CONVERT_TZ(s.`effective_at`, @main_source_utc_offset, '+00:00'), NULL, CONVERT_TZ(s.`created_at`, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.created_at, @main_source_utc_offset, '+00:00')
FROM `category_route` s;
INSERT INTO migration_v2_counts (source_table,target_table,source_rows,staged_rows) SELECT 'category_route','category_route',(SELECT COUNT(*) FROM `category_route`),(SELECT COUNT(*) FROM `v2_stage_category_route`);
INSERT INTO `v2_stage_consultation` (`session_id`,`creator_id`,`category_id`,`status`,`current_engineer_id`,`source`,`resolution_type`,`converted_ticket_id`,`closed_at`,`version`,`created_at`,`updated_at`)
SELECT s.`session_id`, s.`creator_id`, s.`category_id`, s.`status`, s.`current_engineer_id`, CASE s.source WHEN 'DIRECT_HUMAN' THEN 'HUMAN_DIRECT' ELSE s.source END, CASE s.resolved_type WHEN 'CONFIRMED' THEN 'EMPLOYEE_CONFIRMED' WHEN 'AUTO' THEN 'AUTO_RESOLVED' ELSE NULL END, s.ticket_id, CONVERT_TZ(CASE WHEN s.status='CLOSED' THEN s.updated_at END, @main_source_utc_offset, '+00:00'), 0, CONVERT_TZ(s.`created_at`, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.`updated_at`, @main_source_utc_offset, '+00:00')
FROM `consultation` s;
INSERT INTO migration_v2_counts (source_table,target_table,source_rows,staged_rows) SELECT 'consultation','consultation',(SELECT COUNT(*) FROM `consultation`),(SELECT COUNT(*) FROM `v2_stage_consultation`);
INSERT INTO `v2_stage_consultation_message` (`message_id`,`session_id`,`sender_id`,`sender_type`,`client_message_id`,`content`,`citation_json`,`sent_at`,`withdrawn_at`,`withdraw_reason`,`created_at`,`updated_at`)
SELECT s.`message_id`, s.`session_id`, s.`sender_id`, s.`sender_type`, CONCAT('legacy-',s.message_id), s.`content`, NULL, CONVERT_TZ(s.created_at, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.`withdrawn_at`, @main_source_utc_offset, '+00:00'), NULL, CONVERT_TZ(s.`created_at`, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.created_at, @main_source_utc_offset, '+00:00')
FROM `consultation_message` s;
INSERT INTO migration_v2_counts (source_table,target_table,source_rows,staged_rows) SELECT 'consultation_message','consultation_message',(SELECT COUNT(*) FROM `consultation_message`),(SELECT COUNT(*) FROM `v2_stage_consultation_message`);
INSERT INTO `v2_stage_ticket_draft` (`draft_id`,`creator_id`,`nature`,`category_id`,`payload_json`,`last_saved_at`,`expires_at`,`version`,`created_at`,`updated_at`,`title`,`description`,`impact_description`,`urgency_description`,`location`,`contact`,`asset_id`)
SELECT s.`draft_id`, s.user_id, CASE s.nature WHEN 'REQUEST' THEN 'SERVICE_REQUEST' ELSE s.nature END, s.`category_id`, JSON_OBJECT('ticketNature', CASE s.nature WHEN 'REQUEST' THEN 'SERVICE_REQUEST' ELSE s.nature END, 'categoryId',s.category_id,'title',s.title,'description',s.description,'impactDescription',s.impact_description,'urgencyDescription',s.urgency_description,'location',s.location,'contact',s.contact,'assetId',s.asset_id), CONVERT_TZ(s.updated_at, @main_source_utc_offset, '+00:00'), DATE_ADD(CONVERT_TZ(s.updated_at, @main_source_utc_offset, '+00:00'), INTERVAL 7 DAY), 0, CONVERT_TZ(s.updated_at, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.`updated_at`, @main_source_utc_offset, '+00:00'), s.`title`, s.`description`, s.`impact_description`, s.`urgency_description`, s.`location`, s.`contact`, s.`asset_id`
FROM `ticket_draft` s;
INSERT INTO migration_v2_counts (source_table,target_table,source_rows,staged_rows) SELECT 'ticket_draft','ticket_draft',(SELECT COUNT(*) FROM `ticket_draft`),(SELECT COUNT(*) FROM `v2_stage_ticket_draft`);
INSERT INTO `v2_stage_assignment` (`assignment_id`,`biz_type`,`biz_id`,`engineer_id`,`assigned_at`,`response_deadline`,`responded_at`,`end_reason`,`created_at`,`updated_at`)
SELECT s.`assignment_id`, s.`biz_type`, s.`biz_id`, s.`engineer_id`, CONVERT_TZ(s.`assigned_at`, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.`response_deadline`, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.`responded_at`, @main_source_utc_offset, '+00:00'), CASE s.end_reason WHEN 'TIMEOUT_TRANSFER' THEN 'TIMEOUT' WHEN 'TRANSFER_APPLY' THEN 'TRANSFERRED' ELSE s.end_reason END, CONVERT_TZ(s.`created_at`, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.created_at, @main_source_utc_offset, '+00:00')
FROM `assignment` s;
INSERT INTO migration_v2_counts (source_table,target_table,source_rows,staged_rows) SELECT 'assignment','assignment',(SELECT COUNT(*) FROM `assignment`),(SELECT COUNT(*) FROM `v2_stage_assignment`);
INSERT INTO migration_v2_counts (source_table,target_table,source_rows,staged_rows) SELECT 'sla_instance','sla_instance',(SELECT COUNT(*) FROM `sla_instance`),(SELECT COUNT(*) FROM `v2_stage_sla_instance`);
INSERT INTO `v2_stage_sla_pause` (`pause_id`,`sla_id`,`reason_type`,`started_at`,`ended_at`,`operator_id`,`created_at`,`updated_at`)
SELECT s.`pause_id`, s.`sla_id`, CASE s.reason_type WHEN 'SUPPLEMENT' THEN 'PENDING_SUPPLEMENT' WHEN 'EXTERNAL' THEN 'PENDING_EXTERNAL' ELSE s.reason_type END, CONVERT_TZ(s.`started_at`, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.`ended_at`, @main_source_utc_offset, '+00:00'), s.`operator_id`, CONVERT_TZ(s.started_at, @main_source_utc_offset, '+00:00'), CONVERT_TZ(COALESCE(s.ended_at,s.started_at), @main_source_utc_offset, '+00:00')
FROM `sla_pause` s;
