INSERT INTO `v2_stage_notification` (`notification_id`,`event_id`,`receiver_id`,`channel`,`dedup_key`,`status`,`attempts`,`last_error`,`sent_at`,`read_at`,`created_at`,`updated_at`,`title`,`content`,`action_url`)
SELECT s.`notification_id`, s.`event_id`, s.`receiver_id`, CASE s.channel WHEN 'INBOX' THEN 'IN_APP' ELSE s.channel END, s.`dedup_key`, s.`status`, s.`attempts`, s.`last_error`, NULL, NULL, CONVERT_TZ(s.`created_at`, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.`updated_at`, @main_source_utc_offset, '+00:00'), s.`title`, s.`content`, s.`action_url`
