SELECT CAST(s.audit_id AS CHAR), s.`actor_id`, s.`action`, s.`object_type`, s.`object_id`, CASE WHEN s.before_value IS NULL THEN NULL WHEN JSON_VALID(s.before_value) THEN CAST(s.before_value AS JSON) ELSE JSON_OBJECT('legacyText',s.before_value) END, CASE WHEN s.after_value IS NULL THEN NULL WHEN JSON_VALID(s.after_value) THEN CAST(s.after_value AS JSON) ELSE JSON_OBJECT('legacyText',s.after_value) END, s.`reason`, COALESCE(s.request_id,CONCAT('legacy-main-audit-',s.audit_id)), CONVERT_TZ(s.`occurred_at`, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.occurred_at, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.occurred_at, @main_source_utc_offset, '+00:00')
FROM `audit_log` s;
