SELECT s.`transition_id`, s.`ticket_id`, s.`from_status`, s.`to_status`, CONCAT('LEGACY_',UPPER(s.event)), s.`operator_id`, s.`reason`, CONVERT_TZ(s.`occurred_at`, @main_source_utc_offset, '+00:00')
