INSERT INTO `v2_stage_exception_queue` (`exception_id`,`object_type`,`object_id`,`reason_code`,`status`,`claimed_by`,`claimed_at`,`resolved_by`,`resolved_at`,`reason`,`created_at`,`updated_at`,`title`,`detail`,`priority`)
SELECT s.`exception_id`, s.biz_type, s.biz_id, s.exception_type, s.`status`, NULL, NULL, s.`resolved_by`, CONVERT_TZ(s.`resolved_at`, @main_source_utc_offset, '+00:00'), s.resolution, CONVERT_TZ(s.`created_at`, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.`updated_at`, @main_source_utc_offset, '+00:00'), s.`title`, s.`detail`, s.`priority`
FROM `exception_queue` s;
