SELECT s.`user_id`, s.`employee_no`, s.name, s.`department_id`, s.`identity_source`, s.status='ACTIVE', NULL, 0, CONVERT_TZ(s.`created_at`, @main_source_utc_offset, '+00:00'), CONVERT_TZ(s.`updated_at`, @main_source_utc_offset, '+00:00'), s.`password_hash`
FROM `user` s;
